-- Carga del inventario de inmuebles desde Libro1.csv (445 filas).
-- Generado automaticamente. Los catalogos se emparejan por NOMBRE (los ids del Excel no son los de la base).
-- Inmuebles existentes: se actualizan si coinciden proyecto + numero de local + matricula (sin prefijo "001-");
-- conservan id, contratos, egresos, etapa, observaciones y coeficiente. El resto se inserta.
-- Idempotente: re-ejecutarlo actualiza en lugar de duplicar.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

-- ============ Esquema ============
IF COL_LENGTH('dbo.inmueble', 'nivel') IS NULL
    ALTER TABLE inmueble ADD nivel VARCHAR(10) NULL;
IF COL_LENGTH('dbo.inmueble', 'numero_local') < 100
    ALTER TABLE inmueble ALTER COLUMN numero_local VARCHAR(100) NULL;
GO

-- ============ Catalogos ============
WHERE NOT EXISTS (SELECT 1 FROM estado x WHERE x.descripcion = v.d);
WHERE NOT EXISTS (SELECT 1 FROM destinacion x WHERE x.descripcion = v.d);
-- tipo_local es el catalogo de USO del Excel.
WHERE NOT EXISTS (SELECT 1 FROM tipo_local x WHERE x.descripcion = v.d);
WHERE NOT EXISTS (SELECT 1 FROM tipo_inmueble x WHERE x.descripcion = v.d);

-- Proyectos existentes: se conservan sus ids y se renombran al nombre del Excel.
UPDATE p SET nombre = v.nuevo FROM proyecto p JOIN (VALUES
  ('ZONA 2 SUR','Zona 2 Sur'), ('SAN NICOLAS','San Nicolas'), ('MILLA DE ORO','Milla De Oro'),
  ('PIAZZA BELLA','Piazza Bella'), ('SAO PAULO PLAZA','Sao Paulo Plaza'), ('C.CIAL PUNTO CLAVE','Punto Clave'),
  ('C.CIAL AVENTURA','Centro Comercial Aventura'), ('VEGAS 10','Vegas 10'), ('MAYORCA','Mayorca')
) v(viejo, nuevo) ON p.nombre = v.viejo;

CREATE TABLE #map_proyecto (excel_id INT PRIMARY KEY, nombre VARCHAR(200) NOT NULL);

CREATE TABLE #map_estado (excel_id INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL);
CREATE TABLE #map_destinacion (excel_id INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL);
CREATE TABLE #map_uso (excel_id INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL);
CREATE TABLE #map_tipo (excel_id INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL);

-- ============ Datos del Excel ============
CREATE TABLE #carga (
  fila INT PRIMARY KEY, p INT NOT NULL, e INT NOT NULL, d INT NOT NULL, u INT NOT NULL, t INT NOT NULL,
  matricula VARCHAR(50) NULL, numero_local VARCHAR(100) NULL, mesanine BIT NOT NULL, nivel VARCHAR(10) NULL,
  area_piso1 DECIMAL(18,2) NULL, valor_m2_construido DECIMAL(18,2) NULL, valor_comercial DECIMAL(18,2) NULL,
  avaluo_catastral DECIMAL(18,2) NULL, tarifa_catastro DECIMAL(8,4) NULL, predial_anual DECIMAL(18,2) NULL,
  area_libre_priv DECIMAL(18,2) NULL, valor_m2_admon INT NULL, porcent_valor_catastral DECIMAL(18,4) NULL
);

-- ============ Resolucion de catalogos (por nombre) ============
SELECT c.*, pr.id AS id_proyecto, es.id AS id_estado, de.id AS id_destinacion, tl.id AS id_tipo_local, ti.id AS id_tipo_inmueble,
       CASE WHEN c.matricula IS NULL THEN NULL WHEN CHARINDEX('-', c.matricula) > 0 THEN RIGHT(c.matricula, CHARINDEX('-', REVERSE(c.matricula)) - 1) ELSE c.matricula END AS mat_norm
INTO #resuelto
FROM #carga c
LEFT JOIN #map_proyecto mp ON mp.excel_id = c.p     LEFT JOIN proyecto pr ON pr.nombre = mp.nombre
LEFT JOIN #map_estado me ON me.excel_id = c.e       LEFT JOIN estado es ON es.descripcion = me.nombre
LEFT JOIN #map_destinacion md ON md.excel_id = c.d  LEFT JOIN destinacion de ON de.descripcion = md.nombre
LEFT JOIN #map_uso mu ON mu.excel_id = c.u          LEFT JOIN tipo_local tl ON tl.descripcion = mu.nombre
LEFT JOIN #map_tipo mt ON mt.excel_id = c.t         LEFT JOIN tipo_inmueble ti ON ti.descripcion = mt.nombre;

IF EXISTS (SELECT 1 FROM #resuelto WHERE id_proyecto IS NULL OR id_estado IS NULL OR id_destinacion IS NULL OR id_tipo_local IS NULL OR id_tipo_inmueble IS NULL)
    THROW 50001, 'Hay filas del Excel con catalogos sin resolver.', 1;

-- ============ Emparejamiento con inmuebles existentes ============
SELECT r.fila, i.id AS id_inmueble
INTO #match
FROM #resuelto r
JOIN inmueble i ON i.id_proyecto = r.id_proyecto
 AND EXISTS (SELECT r.numero_local, r.mat_norm
             INTERSECT
             SELECT i.numero_local,
                    CASE WHEN i.matricula_inmobiliaria IS NULL THEN NULL
                         WHEN CHARINDEX('-', i.matricula_inmobiliaria) > 0 THEN RIGHT(i.matricula_inmobiliaria, CHARINDEX('-', REVERSE(i.matricula_inmobiliaria)) - 1)
                         ELSE i.matricula_inmobiliaria END);

IF EXISTS (SELECT 1 FROM #match GROUP BY fila HAVING COUNT(*) > 1) OR EXISTS (SELECT 1 FROM #match GROUP BY id_inmueble HAVING COUNT(*) > 1)
    THROW 50002, 'Emparejamiento ambiguo entre el Excel y los inmuebles existentes.', 1;

UPDATE i SET
  id_estado = r.id_estado, id_destinacion = r.id_destinacion, id_tipo_local = r.id_tipo_local, id_tipo_inmueble = r.id_tipo_inmueble,
  mesanine = r.mesanine, nivel = r.nivel,
  area_piso1 = COALESCE(r.area_piso1, i.area_piso1),
  valor_m2_construido = COALESCE(r.valor_m2_construido, i.valor_m2_construido),
  valor_comercial = COALESCE(r.valor_comercial, i.valor_comercial),
  avaluo_catastral = COALESCE(r.avaluo_catastral, i.avaluo_catastral),
  tarifa_catastro = COALESCE(r.tarifa_catastro, i.tarifa_catastro),
  predial_anual = COALESCE(r.predial_anual, i.predial_anual),
  area_libre_priv = COALESCE(r.area_libre_priv, i.area_libre_priv),
  valor_m2_admon = COALESCE(r.valor_m2_admon, i.valor_m2_admon),
  porcent_valor_catastral = COALESCE(r.porcent_valor_catastral, i.porcent_valor_catastral)
FROM inmueble i
JOIN #match m ON m.id_inmueble = i.id
JOIN #resuelto r ON r.fila = m.fila;
DECLARE @actualizados INT = @@ROWCOUNT;

  matricula_inmobiliaria, numero_local, mesanine, nivel, area_piso1, valor_m2_construido, valor_comercial,
  avaluo_catastral, tarifa_catastro, predial_anual, area_libre_priv, valor_m2_admon, porcent_valor_catastral)
SELECT r.id_proyecto, r.id_estado, r.id_destinacion, r.id_tipo_local, r.id_tipo_inmueble,
  r.matricula, r.numero_local, r.mesanine, r.nivel, r.area_piso1, r.valor_m2_construido, r.valor_comercial,
  r.avaluo_catastral, r.tarifa_catastro, r.predial_anual, r.area_libre_priv, r.valor_m2_admon, r.porcent_valor_catastral
FROM #resuelto r
WHERE NOT EXISTS (SELECT 1 FROM #match m WHERE m.fila = r.fila)
ORDER BY r.fila;
DECLARE @insertados INT = @@ROWCOUNT;

-- ============ Verificacion ============
SELECT @actualizados AS actualizados, @insertados AS insertados, (SELECT COUNT(*) FROM inmueble) AS total_inmuebles,
       (SELECT COUNT(*) FROM #carga) AS filas_excel;
SELECT m.fila, i.id, i.numero_local, i.matricula_inmobiliaria FROM #match m JOIN inmueble i ON i.id = m.id_inmueble ORDER BY m.fila;
SELECT p.id, p.nombre, COUNT(i.id) AS inmuebles, CAST(SUM(i.area_piso1) AS DECIMAL(18,2)) AS area_m2
FROM proyecto p LEFT JOIN inmueble i ON i.id_proyecto = p.id GROUP BY p.id, p.nombre ORDER BY p.nombre;

COMMIT;
